// A pretend temperature/humidity sensor (a slow random walk).
const last = context.get('last') || { temperature: 21, humidity: 45 };
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const reading = {
    sensor: 'sensor-1',
    temperature: Math.round((last.temperature + (Math.random() - 0.5) * 0.4) * 100) / 100,
    humidity: Math.round(clamp(last.humidity + (Math.random() - 0.5), 0, 100) * 10) / 10,
    ts: Date.now()
};
context.set('last', reading);
msg.key = reading.sensor;
msg.payload = reading;
return msg;

// msg.payload: the readings collected by the join node (an array).
const readings = msg.payload.filter((r) => r && typeof r.temperature === 'number');
if (readings.length === 0) return null;
let min = Infinity, max = -Infinity, sum = 0, first = Infinity, last = -Infinity;
for (const r of readings) {
    min = Math.min(min, r.temperature);
    max = Math.max(max, r.temperature);
    sum += r.temperature;
    first = Math.min(first, r.ts);
    last = Math.max(last, r.ts);
}
msg.payload = {
    sensor: readings[0].sensor,
    count: readings.length,
    from: new Date(first).toISOString(),
    to: new Date(last).toISOString(),
    temperature: { min: min, avg: Math.round(sum / readings.length * 100) / 100, max: max }
};
return msg;
